 23	import java.time.LocalDate;
 24	import java.time.format.DateTimeParseException;
 25	
 26	public class Application {
 27	
 28	    public static void main(String[] args) {
 29	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 30	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 31	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 32	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 33	
 34	        Database database = new Database(dbUrl, dbUser, dbPassword);
 35	
 36	        RoomRepository roomRepository = new RoomRepositoryImpl(database.getDataSource());
 37	        ReservationRepository reservationRepository = new ReservationRepositoryImpl(database.getDataSource());
 38	        EmailRepository emailRepository = new EmailRepositoryImpl(database.getDataSource());
 39	
 40	        ReservationService reservationService = new ReservationService(
 41	            reservationRepository, roomRepository, emailRepository);
 42	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 43	
 44	        ObjectMapper objectMapper = new ObjectMapper()
 45	            .registerModule(new JavaTimeModule())
 46	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 47	
 48	        Javalin app = Javalin.create(config -> {
 49	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 50	        });
 51	
 52	        app.get("/rooms", ctx -> {
 53	            var rooms = roomRepository.findAll();
 54	            ctx.json(rooms.stream().map(RoomResponse::from).toList());
 55	        });
 56	
 57	        app.post("/reservations", ctx -> {
 58	            try {
 59	                CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
 60	
 61	                validateRequiredFields(req);
 62	
 63	                LocalDate checkIn = parseDate(req.checkIn(), "checkIn");
 64	                LocalDate checkOut = parseDate(req.checkOut(), "checkOut");
 65	
 66	                if (!checkOut.isAfter(checkIn)) {
 67	                    throw new ValidationException("Check-out must be after check-in");
 68	                }
 69	
 70	                RatePlan ratePlan = parseRatePlan(req.ratePlan());
 71	
 72	                Reservation reservation = reservationService.createReservation(
 73	                    req.roomNumber(),
 74	                    req.guestName(),
 75	                    req.guestEmail(),
 76	                    req.guestCpf(),
 77	                    req.companyCnpj(),
 78	                    req.companyName(),
 79	                    req.guestPassport(),
 80	                    req.guestCountry(),
 81	                    checkIn,
 82	                    checkOut,
 83	                    req.guests(),
 84	                    ratePlan
 85	                );
 86	
 87	                ctx.status(201).json(ReservationResponse.from(reservation));
 88	
 89	            } catch (ValidationException e) {
 90	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 91	            } catch (ReservationService.InvalidRequestException e) {
 92	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 93	            } catch (ReservationService.RoomNotFoundException e) {
 94	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
 95	            } catch (ReservationService.RoomUnavailableException e) {
 96	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
 97	            } catch (ReservationService.CapacityExceededException e) {
 98	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
 99	            } catch (IllegalArgumentException e) {
100	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
101	            } catch (Exception e) {
102	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request: " + e.getMessage()));
103	            }
104	        });
105	
106	        app.get("/reservations/{id}", ctx -> {
107	            try {
108	                long id = Long.parseLong(ctx.pathParam("id"));
109	                Reservation reservation = reservationService.getReservation(id);
110	                ctx.json(ReservationResponse.from(reservation));
111	            } catch (ReservationService.ReservationNotFoundException e) {
112	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
113	            }
114	        });
115	
116	        app.post("/reservations/{id}/confirmation", ctx -> {
117	            try {
118	                long id = Long.parseLong(ctx.pathParam("id"));
119	                Reservation reservation = reservationService.confirmReservation(id);
120	                ctx.json(ReservationResponse.from(reservation));
121	            } catch (ReservationService.ReservationNotFoundException e) {
122	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
123	            } catch (ReservationService.OperationNotAllowedException e) {
124	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
125	            }
126	        });
127	
128	        app.post("/reservations/{id}/cancellation", ctx -> {
129	            try {
130	                long id = Long.parseLong(ctx.pathParam("id"));
131	                Reservation reservation = reservationService.cancelReservation(id);
132	                ctx.json(ReservationResponse.from(reservation));
133	            } catch (ReservationService.ReservationNotFoundException e) {
134	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
135	            } catch (ReservationService.OperationNotAllowedException e) {
136	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
137	            }
138	        });
139	
140	        app.post("/reservations/{id}/check-in", ctx -> {
141	            try {
142	                long id = Long.parseLong(ctx.pathParam("id"));
143	                Reservation reservation = reservationService.checkIn(id);
144	                ctx.json(ReservationResponse.from(reservation));
145	            } catch (ReservationService.ReservationNotFoundException e) {
146	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
147	            } catch (ReservationService.OperationNotAllowedException e) {
148	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
149	            }
150	        });
151	
152	        app.post("/reservations/{id}/check-out", ctx -> {
153	            try {
154	                long id = Long.parseLong(ctx.pathParam("id"));
155	                Document document = reservationService.checkOut(id);
156	                ctx.json(DocumentResponse.from(document));
157	            } catch (ReservationService.ReservationNotFoundException e) {
158	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
159	            } catch (ReservationService.OperationNotAllowedException e) {
160	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
161	            }
162	        });
163	
164	        app.get("/reservations/{id}/document", ctx -> {
165	            try {
166	                long id = Long.parseLong(ctx.pathParam("id"));
167	                Document document = reservationService.getDocument(id);
168	                ctx.json(DocumentResponse.from(document));
169	            } catch (ReservationService.ReservationNotFoundException e) {
170	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
171	            } catch (ReservationService.OperationNotAllowedException e) {
172	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
173	            }
174	        });
175	
176	        app.get("/messages", ctx -> {
177	            var emails = emailRepository.findAll();
178	            ctx.json(emails.stream().map(EmailResponse::from).toList());
179	        });
180	
181	        app.get("/reports/occupancy", ctx -> {
182	            try {
183	                String dateStr = ctx.queryParam("date");
184	                if (dateStr == null) {
185	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
186	                    return;
187	                }
188	
189	                LocalDate date = parseDate(dateStr, "date");
190	                String csv = reportService.generateOccupancyReport(date);
191	                ctx.contentType("text/csv; charset=utf-8").result(csv);
192	
193	            } catch (ValidationException e) {
194	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
195	            }
196	        });
197	
198	        app.get("/reports/revenue", ctx -> {
199	            try {
200	                String monthStr = ctx.queryParam("month");
201	                if (monthStr == null) {
202	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
203	                    return;
204	                }
205	
206	                if (!monthStr.matches("\\d{4}-\\d{2}")) {
207	                    throw new ValidationException("Invalid month format, expected yyyy-MM");
208	                }
209	
210	                String[] parts = monthStr.split("-");
211	                int year = Integer.parseInt(parts[0]);
212	                int month = Integer.parseInt(parts[1]);
213	
214	                String csv = reportService.generateRevenueReport(year, month);
215	                ctx.contentType("text/csv; charset=utf-8").result(csv);
216	
217	            } catch (ValidationException e) {
218	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
219	            }
220	        });
221	
222	        app.start(port);
223	        System.out.println("Server started on port " + port);
