225	
226	    private static void validateRequiredFields(CreateReservationRequest req) {
227	        if (req.roomNumber() == null || req.guestName() == null || req.guestEmail() == null ||
228	            req.checkIn() == null || req.checkOut() == null || req.guests() == null || req.ratePlan() == null) {
229	            throw new ValidationException("Missing required fields");
230	        }
231	    }
232	
233	    private static LocalDate parseDate(String dateStr, String fieldName) {
234	        if (dateStr == null) {
235	            throw new ValidationException("Missing " + fieldName);
236	        }
237	
238	        try {
239	            return LocalDate.parse(dateStr);
240	        } catch (DateTimeParseException e) {
241	            throw new ValidationException("Invalid date format for " + fieldName + ", expected yyyy-MM-dd");
242	        }
243	    }
244	
245	    private static RatePlan parseRatePlan(String ratePlan) {
246	        try {
247	            return RatePlan.valueOf(ratePlan);
248	        } catch (Exception e) {
249	            throw new ValidationException("Invalid rate plan: " + ratePlan);
250	        }
251	    }
252	
253	    private static class ValidationException extends RuntimeException {
254	        public ValidationException(String message) {
255	            super(message);
256	        }
257	    }
258	}
