207	                    throw new ValidationException("Invalid month format, expected yyyy-MM");
208	                }
209	
210	                String[] parts = monthStr.split("-");
211	                int year = Integer.parseInt(parts[0]);
212	                int month = Integer.parseInt(parts[1]);
213	
214	                String csv = reportService.generateRevenueReport(year, month);
215	                ctx.contentType("text/csv; charset=utf-8").result(csv);
216	
217	            } catch (ValidationException e) {
218	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
219	            }
220	        });
221	
222	        app.start(port);
223	        System.out.println("Server started on port " + port);
224	    }
