 13	public final class ReportService {
 14	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 15	
 16	    private final ReservationRepository reservationRepository;
 17	    private final RoomRepository roomRepository;
 18	
 19	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 20	        this.reservationRepository = reservationRepository;
 21	        this.roomRepository = roomRepository;
 22	    }
 23	
 24	    public String generateOccupancyReport(LocalDate date) {
 25	        List<Reservation> reservations = reservationRepository.findPaidByNight(date);
 26	        List<Room> allRooms = roomRepository.findAll();
 27	
 28	        StringBuilder csv = new StringBuilder();
 29	        csv.append("room,type,reservation,check_in,check_out\n");
 30	
 31	        for (Reservation r : reservations) {
 32	            csv.append(r.roomNumber()).append(",");
 33	            csv.append(getRoomType(r.roomNumber())).append(",");
 34	            csv.append(r.id()).append(",");
 35	            csv.append(r.checkIn().format(DATE_FORMAT)).append(",");
 36	            csv.append(r.checkOut().format(DATE_FORMAT)).append("\n");
 37	        }
 38	
 39	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
 40	
 41	        return csv.toString();
 42	    }
 43	
 44	    public String generateRevenueReport(int year, int month) {
 45	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(year, month);
 46	
 47	        StringBuilder csv = new StringBuilder();
 48	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 49	
 50	        BigDecimal totalRevenue = BigDecimal.ZERO;
 51	
 52	        for (Reservation r : reservations) {
 53	            BigDecimal revenue = calculateRevenue(r);
 54	
 55	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
 56	                csv.append(r.id()).append(",");
 57	                csv.append(r.roomNumber()).append(",");
 58	                csv.append(r.checkIn().format(DATE_FORMAT)).append(",");
 59	                csv.append(r.checkOut().format(DATE_FORMAT)).append(",");
 60	                csv.append(r.status()).append(",");
 61	                csv.append(formatCsvAmount(revenue)).append("\n");
 62	
 63	                totalRevenue = totalRevenue.add(revenue);
 64	            }
 65	        }
 66	
 67	        csv.append("total,").append(formatCsvAmount(totalRevenue));
 68	
 69	        return csv.toString();
 70	    }
 71	
 72	    private BigDecimal calculateRevenue(Reservation r) {
 73	        BigDecimal paid = r.amountPaid() != null ? r.amountPaid() : BigDecimal.ZERO;
 74	        BigDecimal refunded = r.refund() != null ? r.refund() : BigDecimal.ZERO;
 75	        return paid.subtract(refunded);
 76	    }
 77	
 78	    private String getRoomType(String roomNumber) {
 79	        return roomRepository.findByNumber(roomNumber)
 80	            .map(room -> room.type().name())
 81	            .orElse("UNKNOWN");
 82	    }
 83	
 84	    private String formatCsvAmount(BigDecimal amount) {
 85	        return amount.toString();
 86	    }
 87	}
