107	
108	    public ReservationService(
109	            ReservationRepository reservationRepository,
110	            RoomRepository roomRepository,
111	            EmailRepository emailRepository) {
112	        this.reservationRepository = reservationRepository;
113	        this.roomRepository = roomRepository;
114	        this.emailRepository = emailRepository;
115	        this.pricingService = new PricingService();
116	        this.emailService = new EmailService();
117	    }
