119	    public Reservation createReservation(
120	            String roomNumber,
121	            String guestName,
122	            String guestEmail,
123	            String guestCpf,
124	            String companyCnpj,
125	            String companyName,
126	            String guestPassport,
127	            String guestCountry,
128	            LocalDate checkIn,
129	            LocalDate checkOut,
130	            int guests,
131	            RatePlan ratePlan) {
132	
133	        Room room = roomRepository.findByNumber(roomNumber)
134	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
135	
136	        if (guests < 1) {
137	            throw new InvalidRequestException("At least 1 guest is required");
138	        }
139	
140	        if (guests > room.capacity()) {
141	            throw new CapacityExceededException("Room capacity exceeded");
142	        }
143	
144	        if (!reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut).isEmpty()) {
145	            throw new RoomUnavailableException("Room is not available for the selected dates");
146	        }
147	
148	        GuestType guestType = GuestTypeFactory.create(guestCpf, companyCnpj, companyName, guestPassport, guestCountry);
149	
150	        PricingService.PriceBreakdown pricing = pricingService.calculate(room.type(), checkIn, checkOut, ratePlan);
151	
152	        Reservation reservation = Reservation.builder()
153	            .roomNumber(roomNumber)
154	            .roomType(room.type())
155	            .guestName(guestName)
156	            .guestEmail(guestEmail)
157	            .guestType(guestType)
158	            .checkIn(checkIn)
159	            .checkOut(checkOut)
160	            .guests(guests)
161	            .ratePlan(ratePlan)
162	            .nights(pricing.nights)
163	            .subtotal(pricing.subtotal)
164	            .discount(pricing.discount)
165	            .total(pricing.total)
166	            .build();
167	
168	        return reservationRepository.save(reservation);
169	    }
170	
171	    public Reservation confirmReservation(long id) {
172	        Reservation reservation = getReservation(id);
173	
174	        if (!reservation.canBeConfirmed()) {
175	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.status());
176	        }
177	
178	        reservation.confirm();
179	        reservationRepository.update(reservation);
180	
181	        Document document = reservation.generateDocument();
182	        Email email = emailService.createConfirmationEmail(reservation, document);
183	        emailRepository.save(email);
184	
185	        return reservation;
186	    }
187	
188	    public Reservation cancelReservation(long id) {
189	        Reservation reservation = getReservation(id);
190	
191	        if (!reservation.canBeCancelled()) {
192	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.status());
193	        }
194	
195	        reservation.cancel();
196	        reservationRepository.update(reservation);
197	
198	        return reservation;
199	    }
200	
201	    public Reservation checkIn(long id) {
202	        Reservation reservation = getReservation(id);
203	
204	        if (!reservation.canCheckIn()) {
205	            throw new OperationNotAllowedException("Cannot check-in reservation in status " + reservation.status());
206	        }
207	
208	        reservation.doCheckIn();
209	        reservationRepository.update(reservation);
210	
211	        return reservation;
212	    }
213	
214	    public Document checkOut(long id) {
215	        Reservation reservation = getReservation(id);
216	
217	        if (!reservation.canCheckOut()) {
218	            throw new OperationNotAllowedException("Cannot check-out reservation in status " + reservation.status());
219	        }
220	
221	        reservation.doCheckOut();
222	        reservationRepository.update(reservation);
223	
224	        return reservation.generateDocument();
225	    }
226	
227	    public Document getDocument(long id) {
228	        Reservation reservation = getReservation(id);
229	
230	        if (!reservation.isPaid()) {
231	            throw new OperationNotAllowedException("Document is only available for paid reservations");
232	        }
233	
234	        return reservation.generateDocument();
235	    }
236	
237	    public Reservation getReservation(long id) {
238	        return reservationRepository.findById(id)
239	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found: " + id));
240	    }
241	
242	    public static class RoomNotFoundException extends RuntimeException {
243	        public RoomNotFoundException(String message) {
244	            super(message);
245	        }
246	    }
247	
248	    public static class ReservationNotFoundException extends RuntimeException {
249	        public ReservationNotFoundException(String message) {
250	            super(message);
251	        }
252	    }
253	
254	    public static class InvalidRequestException extends RuntimeException {
255	        public InvalidRequestException(String message) {
256	            super(message);
257	        }
258	    }
259	
260	    public static class RoomUnavailableException extends RuntimeException {
261	        public RoomUnavailableException(String message) {
262	            super(message);
263	        }
264	    }
265	
266	    public static class CapacityExceededException extends RuntimeException {
267	        public CapacityExceededException(String message) {
268	            super(message);
269	        }
270	    }
271	
272	    public static class OperationNotAllowedException extends RuntimeException {
273	        public OperationNotAllowedException(String message) {
274	            super(message);
275	        }
276	    }
