304	package com.pousada.domain.service;
305	
306	import com.pousada.domain.model.RatePlan;
307	import com.pousada.domain.model.RoomType;
308	
309	import java.math.BigDecimal;
310	import java.math.RoundingMode;
311	import java.time.LocalDate;
312	import java.time.Month;
313	
314	public final class PricingService {
315	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
316	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
317	
318	    public static class PriceBreakdown {
319	        public final int nights;
320	        public final BigDecimal subtotal;
321	        public final BigDecimal discount;
322	        public final BigDecimal total;
323	
324	        public PriceBreakdown(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
325	            this.nights = nights;
326	            this.subtotal = subtotal;
327	            this.discount = discount;
328	            this.total = total;
329	        }
330	    }
331	
332	    public PriceBreakdown calculate(RoomType roomType, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
333	        int nights = calculateNights(checkIn, checkOut);
334	        BigDecimal subtotal = calculateSubtotal(roomType, checkIn, checkOut);
335	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
336	        BigDecimal total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
337	
338	        return new PriceBreakdown(nights, subtotal, discount, total);
339	    }
340	
341	    private int calculateNights(LocalDate checkIn, LocalDate checkOut) {
342	        return (int) checkIn.until(checkOut).getDays();
343	    }
344	
345	    private BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
346	        BigDecimal sum = BigDecimal.ZERO;
347	        LocalDate current = checkIn;
348	
349	        while (current.isBefore(checkOut)) {
350	            BigDecimal nightPrice = calculateNightPrice(roomType, current);
351	            sum = sum.add(nightPrice);
352	            current = current.plusDays(1);
353	        }
354	
355	        return sum.setScale(2, RoundingMode.HALF_EVEN);
356	    }
357	
358	    private BigDecimal calculateNightPrice(RoomType roomType, LocalDate date) {
359	        BigDecimal basePrice = roomType.nightlyRate();
360	
361	        if (isHighSeason(date)) {
362	            return basePrice.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
363	        }
364	
365	        return basePrice;
366	    }
367	
368	    private boolean isHighSeason(LocalDate date) {
369	        Month month = date.getMonth();
370	        int day = date.getDayOfMonth();
371	
372	        if (month == Month.JULY) {
373	            return true;
374	        }
375	
376	        if (month == Month.DECEMBER && day >= 15) {
377	            return true;
378	        }
379	
380	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
381	            return true;
382	        }
383	
384	        return false;
385	    }
386	
387	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
388	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
389	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
390	        }
391	        return BigDecimal.ZERO;
392	    }
393	}

