 25	    private void initialize() {
 26	        try (Connection conn = dataSource.getConnection();
 27	             Statement stmt = conn.createStatement()) {
 28	
 29	            stmt.execute("""
 30	                CREATE TABLE IF NOT EXISTS rooms (
 31	                    number VARCHAR(10) PRIMARY KEY,
 32	                    type VARCHAR(20) NOT NULL
 33	                )
 34	            """);
 35	
 36	            stmt.execute("""
 37	                CREATE TABLE IF NOT EXISTS reservations (
 38	                    id BIGSERIAL PRIMARY KEY,
 39	                    room_number VARCHAR(10) NOT NULL,
