    28	
    29	        assertThat(document.title()).isEqualTo("Comprovante de reserva");
    30	        assertThat(document.guestCpf()).isEqualTo("111.222.333-44");
    31	        assertThat(document.text()).contains("Comprovante de reserva nº 7");
    32	        assertThat(document.text()).contains("Hóspede: Carla Dias (CPF 111.222.333-44)");
    33	        assertThat(document.text()).contains("Quarto: 201 (DELUXE)");
    34	        assertThat(document.text()).contains("Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias");
    35	        assertThat(document.text()).contains("779,80");
    36	    }
    37	
